// IsTestRunPrimaryKeyError checks if the error is a primary_key constraint violation on test_runs
func IsTestRunPrimaryKeyError(err error) bool {
	return sqlerr.IsConstraintNamed(err, TestRunConstraintPkey)
}

// IsSuitePrimaryKeyError checks if the error is a primary_key constraint violation on suites
func IsSuitePrimaryKeyError(err error) bool {
	return sqlerr.IsConstraintNamed(err, SuiteConstraintPkey)
}

// IsSuiteRunPrimaryKeyError checks if the error is a primary_key constraint violation on suite_runs
